467	export function shapedThread<T extends ThreadEntry>(comments: readonly T[], readers: TurnReaders): ShapedThread<T> {
468	  const kept: T[] = [];
469	  const events: TurnEvent[] = [];
470	  // The ask id of the newest claim not yet answered — the claimed-and-unanswered
471	  // state. Undefined is a person's turn, whatever the events say: the claim is what
472	  // makes the ball the agent's (#285), and an unclaimed ask is a run that has not
473	  // started yet rather than one that is working.
474	  let openClaim: number | undefined;
475	  let openClaimRun: number | undefined;
476	  for (const entry of comments) {
477	    if (entry.isHuman && openClaim !== undefined) continue;
478	    kept.push(entry);
479	    if (!entry.quoted) {
480	      // Claims and their answers move the state in the same walk that shapes the
481	      // thread, so a reader of the shaped comments and the holder can never
482	      // disagree about where the ball was. A quotation carries neither: the tags in
483	      // it are the removed author's words, not the thread's own (see
484	      // `ThreadEntry.quoted`).
485	      const event = eventOf(entry, readers);
486	      const claim = readers.claim(entry.body);
487	      if (claim !== undefined) {
488	        openClaim = claim.ask;
489	        openClaimRun = claim.run;
490	      } else if (openClaim !== undefined) {
491	        const answered = readers.answeredAsk(entry.body);
492	        // A `waiting` ending does not close the claim it answers (#208): it PARKS
493	        // the turn on the agents working under this node, and the ball does not
494	        // come back until the aggregation re-invokes the parent. Keeping the claim
495	        // open across the park is what makes a person's comment during the wait an
496	        // interruption the shaping excludes -- and the guard removes -- instead of
497	        // a turn the person holds. The claim closes when the re-invoked run claims
498	        // the parked ask and answers it, or when a `/stop` ends the park.
499	        if (answered !== undefined && answered === openClaim && event !== "waiting") openClaim = undefined;
500	      }
501	      if (event !== undefined) events.push(event);
502	    }
503	  }
504	  return {
505	    comments: kept,
506	    events,
507	    holder: openClaim !== undefined ? "agent" : "person",
508	    ...(openClaim !== undefined ? { openClaim: { ask: openClaim, run: openClaimRun ?? 0 } } : {}),
509	  };
510	}
