526	 * handed back through the message that replaced it.
527	 *
528	 * Returns "" when nothing in the thread asks for an agent.
529	 */
530	export function latestRequestedAgent(body: string, comments: readonly ThreadEntry[], readers: TurnReaders): string {
531	  const { comments: kept } = shapedThread(comments, readers);
532	  for (let index = kept.length - 1; index >= 0; index -= 1) {
533	    const entry = kept[index]!;
534	    if (entry.quoted) continue;
