151	export function sweepStaleLocks(opts: {
152	  readonly repo: string;
153	  /** This sweep's own run id, for the endings it writes. `0` outside a run. */
154	  readonly runId: number;
155	  /** The instant to judge ages against. Passed in, so a test can name it. */
156	  readonly nowMs: number;
157	  readonly log?: (message: string) => void;
158	}): SweepSummary {
159	  const log = opts.log ?? ((message: string) => console.error(message));
160	  const nodes = inProgressNodes(opts.repo, getLabel("in_progress"));
161	  log(`stale sweep: ${nodes.length} node(s) wearing the in-progress label`);
162	
163	  let released = 0;
164	  let held = 0;
165	  let undetermined = 0;
166	  let failed = 0;
167	
168	  for (const number of nodes) {
169	    let read: ReturnType<typeof readNodeLock>;
170	    try {
171	      read = readNodeLock(opts.repo, number, opts.nowMs);
172	    } catch (error) {
173	      undetermined += 1;
174	      log(`stale sweep: could not read #${number}'s thread, so it is left alone: ${(error as Error).message}`);
175	      continue;
176	    }
177	
178	    if (read.verdict === "hold") {
179	      held += 1;
180	      continue;
181	    }
182	    // The ask the ending must answer: the claim's, or — for a park whose claim a person
183	    // already took away by hand — the parked ending's own, which is what the aggregation
184	    // would have answered. A `release` with neither cannot be written, so it is reported as
185	    // undetermined rather than posted answering ask 0.
186	    const ask = read.lock.claim?.ask ?? read.lock.park?.answers;
187	    if (read.verdict === "undetermined" || ask === undefined) {
188	      undetermined += 1;
189	      log(`stale sweep: #${number}'s lock is not something this sweep can call; left alone`);
190	      continue;
191	    }
192	
193	    const parked = read.lock.park !== undefined;
194	    const agent = mostRecentAgentOn(opts.repo, number) || "atomaton";
195	    const body = parked ? staleParkNotice(agent, ask, opts.runId) : staleClaimNotice(agent, ask, opts.runId);
196	    const posted = gh("issue", "comment", String(number), "--repo", opts.repo, "--body", body);
197	    if (posted.code !== 0) {
198	      failed += 1;
199	      log(`::error::stale sweep: could not post the ending on #${number}: ${posted.stderr || posted.stdout}`);
200	      continue;
201	    }
202	    released += 1;
203	    log(`stale sweep: ${parked ? "released a missed park" : "released a dead claim"} on #${number}`);
204	
205	    // The ending IS the release: it answers the claim's ask, so every reader that was
206	    // waiting for one stops waiting. Proven, not assumed — a release that did not take
207	    // effect is a node still locked with a comment on it saying otherwise, which is the
208	    // worst of the states here. The labels come after, best-effort, on the same rule the
209	    // per-run watch applies: the thread is the record and the label is its cache.
210	    // The proof asks the question the judgement answered, not "is any claim open": a comment
211	    // that arrives between the release and this read is a NEW claim by a new run, and
212	    // reading that as "the release did not take" would turn a healed node into a red run and
213	    // skip its label write.
214	    const answeredLock = read.lock.claim;
215	    let stillHeld: boolean;
216	    try {
217	      const after = lockOn(opts.repo, number).claim;
218	      stillHeld =
219	        answeredLock !== undefined
220	          ? after?.ask === answeredLock.ask && after?.run === answeredLock.run
221	          : after !== undefined && after.ask === ask;
222	    } catch (error) {
223	      failed += 1;
224	      log(`::error::stale sweep: released #${number} but could not read the thread back to check it: ${(error as Error).message}`);
225	      continue;
226	    }
227	    if (stillHeld) {
228	      failed += 1;
229	      log(`::error::stale sweep: #${number} still holds a claim after the ending was posted; this sweep will report it again`);
